      "arFull": "رَبَّنَا وَاَدْخِلْهُمْ جَنّٰتِ عَدْنِ لَّتِیْ وَعَدْتَّهُمْ وَمَنْ صَلَحَ مِنْ اٰبَآىِٕهِمْ وَاَزْوَاجِهِمْ وَذُرِّیّٰتِهِمْ ؕ اِنَّكَ اَنْتَ الْعَزِیْزُ الْحَكِیْمُ ۟ۙ",
      "ur": "اے ہمارے رب! تو انہیں ہمیشگی والی جنتوں میں لے جا جن کا تو نے ان سے وعده کیا ہے اور ان کے باپ دادوں اور بیویوں اور اوﻻد میں سے (بھی) ان (سب) کو جو نیک عمل ہیں[1] ۔ یقیناً تو تو غالب و باحکمت ہے.",
      "en": "Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their forefathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.",
      "footnotesUr": "[1] یعنی ان سب کو جنت میں جمع فرما دے تاکہ ایک دوسرےکو دیکھ کر ان کی آنکھیں ٹھنڈی ہوں۔ اس مضمون کو دوسرے مقام پر اس طرح بیان فرمایا گیا ہے «وَالَّذِينَ آمَنُوا وَاتَّبَعَتْهُمْ ذُرِّيَّتُهُمْ بِإِيمَانٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَا أَلَتْنَاهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍ» (الطور: 21) ”وہ لوگ جو ایمان لائےاور ان ہی کی پیروی ان کی اولاد نے ایمان کے ساتھ کی۔ ملا دیا ہم نے ان کے ساتھ ان کی اولاد کو اورہم نے ان کے عملوں میں سے کچھ کم نہیں کیا“۔ یعنی سب کو جنت میں اس طرح یکساں مرتبہ دے دیا کہ ادنیٰ کو بھی اعلیٰ مقام عطا کر دیا۔ یہ نہیں کیا کہ اعلیٰ مقام میں کمی کر کے انہیں ادنیٰ مقام پر لے آئے،بلکہ ادنیٰ کو اٹھا کر اعلیٰ کردیا اور اس کےعمل کی کمی کو اپنے فضل و کرم سے پورا کر دیا۔",
      "footnotesEn": null,
