      "number": 11,
      "arFull": "قَالُوْا رَبَّنَاۤ اَمَتَّنَا اثْنَتَیْنِ وَاَحْیَیْتَنَا اثْنَتَیْنِ فَاعْتَرَفْنَا بِذُنُوْبِنَا فَهَلْ اِلٰی خُرُوْجٍ مِّنْ سَبِیْلٍ ۟",
      "ur": "وه کہیں گے اے ہمارے پروردگار! تو نے ہمیں دوبار مارا اور دو بار ہی جلایا[1] ، اب ہم اپنے گناہوں کے اقراری ہیں[2]، تو کیا اب کوئی راه نکلنے کی بھی ہے؟[3]",
      "en": "They will say, \"Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?\"",
      "footnotesUr": "[1] جمہور مفسرین کی تفسیر کے مطابق، دو موتوں میں سے پہلی موت تو وہ نطفہ ہے جو باپ کی پشت میں ہوتا ہے۔ یعنی اس کے وجود (ہست) سے پہلےاس کے عدم وجود (نیست) کو موت سے تعبیر کیا گیا ہے۔ اور دوسری موت وہ ہے جس سے انسان اپنی زندگی گزار کر ہمکنار ہوتا اور اس کے بعد قبر میں دفن ہوتا ہے اور دو زندگیوں میں سے پہلی زندگی، یہ دینوی زندگی ہے، جس کا آغاز ولادت سے اور اختتام، وفات پرہوتا ہے۔ اور دوسری زندگی وہ ہے جو قیامت والے دن قبروں سے اٹھنے کے بعد حاصل ہوگی۔ انہی دو موتوں اور دو زندگیوں کاتذکرہ، «وَكُنْتُمْ أَمْوَاتًا فَأَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ» (البقرة: 28) میں بھی کیا گیا ہے۔\n[2] یعنی جہنم میں اعتراف کریں گے، جہاں اعتراف کا کوئی فائدہ نہیں اور وہاں پشیمان ہوں گے جہاں پشیمانی کی کوئی حیثیت نہیں۔\n[3] یہ وہی خواہش ہے جس کا تذکرہ قرآن مجیدمیں متعدد مقامات پر کیا گیا ہے کہ ہمیں دوبارہ زمین پر بھیج دیا جائے، تاکہ ہم نیکیاں کما کر لائیں۔",
      "footnotesEn": null,
