      "arFull": "اَلْیَوْمَ تُجْزٰی كُلُّ نَفْسٍ بِمَا كَسَبَتْ ؕ لَا ظُلْمَ الْیَوْمَ ؕ اِنَّ اللّٰهَ سَرِیْعُ الْحِسَابِ ۟",
