      "arFull": "وَاَنْذِرْهُمْ یَوْمَ الْاٰزِفَةِ اِذِ الْقُلُوْبُ لَدَی الْحَنَاجِرِ كٰظِمِیْنَ ؕ۬ مَا لِلظّٰلِمِیْنَ مِنْ حَمِیْمٍ وَّلَا شَفِیْعٍ یُّطَاعُ ۟ؕ",
      "ur": "اور انہیں بہت ہی قریب آنے والی[1] (قیامت سے) آگاه کر دیجئے، جب کہ دل حلق تک پہنچ جائیں گے اور سب خاموش ہوں گے[2]، ﻇالموں کا نہ کوئی دلی دوست ہوگا نہ سفارشی، کہ جس کی بات مانی جائے گی.",
      "en": "And warn them, [O Muḥammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.",
      "footnotesUr": "[1] آزِفَةٌ کے معنی ہیں قریب آنے والی۔ یہ قیامت کا نام ہے، اس لیے کہ وہ بھی قریب آنے والی ہے۔\n[2] یعنی اس دن خوف کی وجہ سے دل اپنی جگہ سے ہٹ جائیں گے۔ كَاظِمِينَ غم سے بھرے ہوئے، یا روتے ہوئے، یا خاموش، اس کےتینوں معنی کیے گئے ہیں۔",
