      "en": "And We did certainly send Moses with Our signs and a clear authority[1367]",
      "footnotesUr": "[1] آیات سے مراد وہ نو نشانیاں بھی ہو سکتی ہیں جن کا ذکر پہلے گزر چکا ہے، یا عصا اور ید بیضا والے دو بڑے واضح معجزات بھی سُلْطَانٍ مُبِينٍ سے مراد قوی دلیل اور حجت واضحہ، جس کا کوئی جواب ان کی طرف سے ممکن نہیں تھا، بجز ڈھٹائی اور بےشرمی کے۔",
