      "arFull": "قَالَ الَّذِیْنَ اسْتَكْبَرُوْۤا اِنَّا كُلٌّ فِیْهَاۤ ۙ اِنَّ اللّٰهَ قَدْ حَكَمَ بَیْنَ الْعِبَادِ ۟",
      "ur": "وه بڑے لوگ جواب دیں گے ہم تو سبھی اس آگ میں ہیں، اللہ تعالیٰ اپنے بندوں کے درمیان فیصلے کر چکا ہے.",
