      "number": 59,
      "arFull": "اِنَّ السَّاعَةَ لَاٰتِیَةٌ لَّا رَیْبَ فِیْهَا وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا یُؤْمِنُوْنَ ۟",
